/*
 * Standalone model of the fs/hugetlbfs/inode.c Opt_pagesize state machine.
 *
 * This is NOT the kernel build. It is a self-contained executable model that
 * encodes the pre-fix and post-fix control flow to exercise the CVE-2024-0841
 * security invariant:
 *
 *   an invalid "pagesize" must NOT overwrite ctx->hstate (which defaults to
 *   &default_hstate with a non-NULL value), because hugetlbfs_fill_super()
 *   later dereferences it through huge_page_size()/huge_page_shift().
 *
 * Positive path  : valid pagesize resolves to a hstate and stores it.
 * Negative path  : invalid pagesize reproduces the bug pre-fix (hstate == NULL)
 *                  and must keep the previous hstate post-fix.
 */
#include <stdio.h>
#include <stddef.h>

typedef struct hstate {
	unsigned long pagesz;
} hstate;

static hstate default_hstate = { 2UL * 1024 * 1024 };
static hstate hstates[2] = { { 2UL * 1024 * 1024 }, { 1UL * 1024 * 1024 * 1024 } };

struct hugetlbfs_fs_context {
	hstate *hstate;
};

/* mirror of mm/hugetlb.c size_to_hstate(): NULL for unsupported sizes */
static hstate *size_to_hstate(unsigned long size)
{
	int i;

	for (i = 0; i < 2; i++) {
		if (hstates[i].pagesz == size)
			return &hstates[i];
	}
	return NULL;
}

/* pre-fix parse_param Opt_pagesize arm */
static int parse_prefix(struct hugetlbfs_fs_context *ctx, unsigned long ps)
{
	ctx->hstate = size_to_hstate(ps);
	if (!ctx->hstate)
		return -22; /* -EINVAL */
	return 0;
}

/* candidate (post-fix) parse_param Opt_pagesize arm */
static int parse_postfix(struct hugetlbfs_fs_context *ctx, unsigned long ps)
{
	hstate *h;

	h = size_to_hstate(ps);
	if (!h)
		return -22; /* -EINVAL */
	ctx->hstate = h;
	return 0;
}

int main(void)
{
	struct hugetlbfs_fs_context ctx;
	int rc, failures = 0;

	/* negative path, pre-fix: reproduce the corruption that leads to the oops */
	ctx.hstate = &default_hstate;
	rc = parse_prefix(&ctx, 1024);
	if (rc != -22) {
		printf("FAIL: pre-fix model did not return -EINVAL for invalid pagesize\n");
		failures++;
	}
	if (ctx.hstate != NULL) {
		printf("FAIL: pre-fix model did not reproduce NULL ctx->hstate\n");
		failures++;
	} else {
		printf("OK: pre-fix model reproduces NULL ctx->hstate (CVE condition)\n");
	}

	/* negative path, post-fix: guard must preserve the previous hstate */
	ctx.hstate = &default_hstate;
	rc = parse_postfix(&ctx, 1024);
	if (rc != -22) {
		printf("FAIL: post-fix returned %d instead of -EINVAL\n", rc);
		failures++;
	}
	if (ctx.hstate == NULL) {
		printf("FAIL: post-fix left ctx->hstate NULL (vulnerability present)\n");
		failures++;
	} else if (ctx.hstate != &default_hstate) {
		printf("FAIL: post-fix overwrote default hstate on error path\n");
		failures++;
	} else {
		printf("OK: post-fix preserves &default_hstate on invalid pagesize\n");
	}

	/* positive path, post-fix: valid pagesize is still stored */
	ctx.hstate = &default_hstate;
	rc = parse_postfix(&ctx, 2UL * 1024 * 1024);
	if (rc != 0 || ctx.hstate != &hstates[0]) {
		printf("FAIL: post-fix lost the valid pagesize mapping\n");
		failures++;
	} else {
		printf("OK: post-fix stores the valid hstate\n");
	}

	if (failures)
		return 1;
	printf("model checks passed\n");
	return 0;
}

#!/usr/bin/env python3
"""Structural check of the patched Opt_pagesize arm.

Reads fs/hugetlbfs/inode.c from the current working directory (the validator's
clean checkout with generated.patch applied) and asserts the CVE-2024-0841
invariant ordering:

    h = size_to_hstate(ps);
    if (!h) { ... return -EINVAL; }
    ctx->hstate = h;

and that the pre-fix "ctx->hstate = size_to_hstate(ps);" form is gone.
"""
import re
import sys
from pathlib import Path

SRC = Path("fs/hugetlbfs/inode.c")

text = SRC.read_text(encoding="utf-8", errors="replace")

# Isolate the Opt_pagesize case arm.
start = text.find("case Opt_pagesize:")
if start < 0:
    print("FAIL: case Opt_pagesize not found")
    sys.exit(1)
end = text.find("case Opt_min_size:", start)
if end < 0:
    print("FAIL: could not delimit Opt_pagesize arm")
    sys.exit(1)
arm = text[start:end]

errors = []

if "ctx->hstate = size_to_hstate(ps);" in arm:
    errors.append("pre-fix form 'ctx->hstate = size_to_hstate(ps);' still present")

m_h = re.search(r"\bh\s*=\s*size_to_hstate\(ps\);", arm)
m_if = re.search(r"if\s*\(!h\)\s*\{", arm)
m_store = re.search(r"ctx->hstate\s*=\s*h;", arm)

if not m_h:
    errors.append("local 'h = size_to_hstate(ps);' missing")
if not m_if:
    errors.append("guard 'if (!h)' missing")
if not m_store:
    errors.append("deferred 'ctx->hstate = h;' missing")

if m_h and m_if and m_store:
    # The store must come after the full guard block (after its closing brace).
    brace = arm.find("{", m_if.start())
    depth = 0
    close = -1
    for i in range(brace, len(arm)):
        if arm[i] == "{":
            depth += 1
        elif arm[i] == "}":
            depth -= 1
            if depth == 0:
                close = i
                break
    if close < 0:
        errors.append("could not find end of guard block")
    else:
        if not (m_h.start() < m_if.start() < close < m_store.start()):
            errors.append(
                "ordering wrong: expected h-assignment < guard < guard-end < ctx->hstate=h"
            )
    if "-EINVAL" not in arm:
        errors.append("error return -EINVAL missing from guard")

if errors:
    print("FAIL: structural check of Opt_pagesize failed:")
    for item in errors:
        print("  -", item)
    sys.exit(1)

print("OK: Opt_pagesize computes into local h, guards, then stores ctx->hstate = h")
sys.exit(0)

